// Extrait toutes les URLs du sitemap.xml brut
const xml = $input.first().json.data || $input.first().json.body || '';
const matches = [...xml.matchAll(/<loc>(.*?)<\/loc>/g)];
const urls = matches.map(m => m[1]);
return urls.map(url => ({ json: { url } }));

// Crawle chaque URL du sitemap et calcule les metriques SEO on-page
const items = $input.all();
const results = [];

for (const item of items) {
  const url = item.json.url;
  try {
    const res = await this.helpers.httpRequest({
      url,
      method: 'GET',
      returnFullResponse: true,
      ignoreHttpStatusErrors: true
    });
    const html = res.body || '';
    const htmlSize = Buffer.byteLength(html, 'utf8');

    const titleMatch = html.match(/<title>(.*?)<\/title>/i);
    const title = titleMatch ? titleMatch[1] : '';

    const bodyMatch = html.match(/<body[^>]*>([\s\S]*)<\/body>/i);
    const bodyHtml = bodyMatch ? bodyMatch[1] : html;
    const textOnly = bodyHtml
      .replace(/<script[\s\S]*?<\/script>/gi, '')
      .replace(/<style[\s\S]*?<\/style>/gi, '')
      .replace(/<[^>]+>/g, ' ')
      .replace(/&[a-z]+;/gi, ' ')
      .replace(/\s+/g, ' ')
      .trim();

    const wordCount = textOnly.length ? textOnly.split(' ').filter(Boolean).length : 0;
    const textSize = Buffer.byteLength(textOnly, 'utf8');
    const ratio = htmlSize > 0 ? +(textSize / htmlSize).toFixed(3) : 0;

    const rawLinks = [...html.matchAll(/href="(\/[a-zA-Z0-9\-_\/]*)"/g)].map(m => m[1]);
    const internalLinks = [...new Set(rawLinks)].filter(
      l => !l.match(/\.(png|jpg|jpeg|svg|webp|css|js|ico)$/i)
    );

    results.push({
      json: {
        _source: 'onpage',
        url,
        httpStatus: res.statusCode,
        title,
        titleLength: title.length,
        wordCount,
        textHtmlRatio: ratio,
        internalLinksCount: internalLinks.length
      }
    });
  } catch (e) {
    results.push({
      json: { _source: 'onpage', url, error: e.message }
    });
  }
}

return results;

const rows = ($input.first().json.rows) || [];
return rows.map(r => ({
  json: {
    _source: 'gsc',
    url: r.keys[0],
    clicks: r.clicks,
    impressions: r.impressions,
    ctr: +(r.ctr * 100).toFixed(2),
    position: +r.position.toFixed(1)
  }
}));

// Verifie les Core Web Vitals sur les pages cles via PageSpeed Insights (API publique)
// Remplace COLLE_TA_CLE_API_ICI par une cle API Google Cloud (PageSpeed Insights API activee, gratuite)
const API_KEY = 'AIzaSyDrrDvZ6_1PVMBO3yklDoAD47h3jUldpo4';
const keyPages = [
  'https://www.kls3-dev.com/',
  'https://www.kls3-dev.com/blog',
  'https://www.kls3-dev.com/contact',
  'https://www.kls3-dev.com/cas-clients',
  'https://www.kls3-dev.com/diagnostic'
];

const results = [];
for (const url of keyPages) {
  try {
    const psiUrl = `https://www.googleapis.com/pagespeedonline/v5/runPagespeed?url=${encodeURIComponent(url)}&strategy=mobile&key=${API_KEY}`;
    const res = await this.helpers.httpRequest({ url: psiUrl, method: 'GET', json: true });
    const lighthouse = res.lighthouseResult;
    results.push({
      json: {
        _source: 'psi',
        url,
        performanceScore: Math.round((lighthouse.categories.performance.score || 0) * 100),
        lcp: lighthouse.audits['largest-contentful-paint'].displayValue,
        cls: lighthouse.audits['cumulative-layout-shift'].displayValue
      }
    });
  } catch (e) {
    results.push({ json: { _source: 'psi', url, error: e.message } });
  }
}
return results;

const items = $input.all().map(i => i.json);

const onpage = items.filter(i => i._source === 'onpage' && !i.error);
const gsc = items.filter(i => i._source === 'gsc');
const psi = items.filter(i => i._source === 'psi' && !i.error);
const historyRows = items.filter(i => i.date);

// Jointure onpage + gsc par url
const pages = onpage.map(p => {
  const g = gsc.find(x => x.url === p.url || p.url.endsWith(x.url) || x.url.endsWith(p.url.replace(/^https?:\/\/[^\/]+/, '')));
  return { ...p, clicks: g ? g.clicks : 0, impressions: g ? g.impressions : 0, position: g ? g.position : null };
});

// Snapshot precedent (derniere ligne par date)
const previous = historyRows.sort((a, b) => new Date(b.date) - new Date(a.date))[0] || null;

// Detection d'anomalies
const anomalies = [];

const titlesTooLong = pages.filter(p => p.titleLength > 60);
titlesTooLong.forEach(p => anomalies.push({
  name: `Title trop long (${p.titleLength}c) - ${p.url}`,
  desc: `Le title de ${p.url} fait ${p.titleLength} caracteres, au-dela des 60 recommandes.`,
  priority: 'P2'
}));

const lowRatio = pages.filter(p => p.textHtmlRatio < 0.10);
lowRatio.forEach(p => anomalies.push({
  name: `Ratio texte/HTML faible - ${p.url}`,
  desc: `Ratio de ${p.textHtmlRatio} sur ${p.url}, sous le seuil de 0.10.`,
  priority: 'P2'
}));

const thin = pages.filter(p => p.wordCount < 300);
thin.forEach(p => anomalies.push({
  name: `Page mince (${p.wordCount} mots) - ${p.url}`,
  desc: `${p.url} ne contient que ${p.wordCount} mots visibles.`,
  priority: 'P3'
}));

const weakLinked = pages.filter(p => p.internalLinksCount <= 1);
weakLinked.forEach(p => anomalies.push({
  name: `Maillage interne faible - ${p.url}`,
  desc: `${p.url} n'a que ${p.internalLinksCount} lien(s) interne(s) sortant(s) detecte(s).`,
  priority: 'P2'
}));

const errors404 = onpage.filter(p => p.httpStatus === 404);
errors404.forEach(p => anomalies.push({
  name: `404 detectee - ${p.url}`,
  desc: `${p.url} retourne un 404 lors du crawl hebdomadaire.`,
  priority: 'P1'
}));

// Comparaison avec la semaine precedente
const totalClicks = pages.reduce((s, p) => s + (p.clicks || 0), 0);
const totalImpressions = pages.reduce((s, p) => s + (p.impressions || 0), 0);
const positions = pages.filter(p => p.position).map(p => p.position);
const avgPosition = positions.length ? +(positions.reduce((a, b) => a + b, 0) / positions.length).toFixed(1) : null;
const avgWordCount = pages.length ? Math.round(pages.reduce((s, p) => s + p.wordCount, 0) / pages.length) : 0;
const avgRatio = pages.length ? +(pages.reduce((s, p) => s + p.textHtmlRatio, 0) / pages.length).toFixed(3) : 0;

const deltas = previous ? {
  clicksDelta: totalClicks - previous.totalClicks,
  impressionsDelta: totalImpressions - previous.totalImpressions,
  positionDelta: avgPosition !== null && previous.avgPosition ? +(avgPosition - previous.avgPosition).toFixed(1) : null
} : { clicksDelta: null, impressionsDelta: null, positionDelta: null };

const psiHomepage = psi.find(p => p.url === 'https://www.kls3-dev.com/');

const snapshotRow = {
  date: $now.toFormat('yyyy-MM-dd'),
  totalClicks,
  totalImpressions,
  avgPosition,
  totalPages: pages.length,
  avgWordCount,
  avgRatio,
  titlesTooLong: titlesTooLong.length,
  lowRatioPages: lowRatio.length,
  thinPages: thin.length,
  weakLinkedPages: weakLinked.length,
  psiHomepageScore: psiHomepage ? psiHomepage.performanceScore : null,
  issuesJSON: JSON.stringify(anomalies.map(a => a.name))
};

return [{
  json: {
    pages,
    psi,
    deltas,
    snapshotRow,
    anomalies,
    generatedAt: $now.toISO()
  }
}];

const data = $input.first().json;

const promptText = "Tu es un expert SEO qui redige une synthese hebdomadaire pour Eric, fondateur de KLS3. Voici les donnees brutes de la semaine (JSON) : " + JSON.stringify(data) + ". Redige en francais, ton direct et professionnel (style KLS3, vouvoiement). IMPORTANT : reponds uniquement en HTML simple, sans markdown, en utilisant ces balises : <p> pour les paragraphes, <strong> pour le gras, <ul><li> pour les listes. N utilise JAMAIS de dieses, asterisques, ou autre syntaxe markdown. Structure : un paragraphe de synthese de 3-4 phrases sur l etat general du SEO, puis une liste <ul> de 3 a 5 actions prioritaires classees par impact, chaque <li> commencant par <strong>le titre de l action</strong> suivi d une phrase d explication.";

const bodyObject = {
  model: "claude-sonnet-4-6",
  max_tokens: 1500,
  messages: [{ role: "user", content: promptText }]
};

return [{ json: { anthropicBody: JSON.stringify(bodyObject) } }];
